(5019862, 732415, 99263, '<td valign="top">Excellent shot but I wish you had not cropped off the top of the guys head and hand and also the guys handicapped hand on the right should have been in the frame especially as the reason he is begging is stated quite clearly on the card around his neck. Was this taken in South Africa by any chance?</td>', 'Excellent shot but I wish you had not cropped off the top of the guys head and hand and also the guys handicapped hand on the right should have been in the frame especially as the reason he is begging is stated quite clearly on the card around his neck. Was this taken in South Africa by any chance?', '2008-10-22 05:46:35.000000', NULL, 1),
(5019867, 732446, 99263, '<td valign="top">This does really capture poverty. Was this shot taken in South Africa by any chance?</td>', 'This does really capture poverty. Was this shot taken in South Africa by any chance?', '2008-10-22 05:57:58.000000', NULL, 1),
(5019870, 732249, 18450, '<td valign="top">This image breaks my heart. Technically the shot has flaws IMO (softish focus, slightly blown hightlights) but it has real soul.</td>', 'This image breaks my heart. Technically the shot has flaws IMO (softish focus, slightly blown hightlights) but it has real soul.', '2008-10-22 06:09:46.000000', NULL, 1),
